from string import ascii_uppercase as alfa

cifrado = ""

dicc = {}

for letra in alfa:
    dicc[letra] = cifrado.count(letra)

#print(dicc)

dicc_ord = dict(sorted(dicc.items(), key=lambda item: item[1], reverse=True))

print(dicc_ord)

